                if length % 2 == 1:
                    prefix_length = i
                    suffix_length = n - j - 1
                    if prefix_length == suffix_length:
                        if length > max_length:
                            max_length = length
                            result = [(1, prefix_length), (i + 1, length), (j + 2, suffix_length)]
                    elif prefix_length > suffix_length:
                        if length + 2 * suffix_length > max_length:
                            max_length = length + 2 * suffix_length
                            result = [(1, suffix_length), (i - suffix_length + 1, length), (j + 2, suffix_length)]
